INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A2', 'yesterday', 'What I Did Yesterday', 'Talk about the past: where you went and what you did.', 'Monday morning: a colleague asks about your weekend.', 'What you did ends in -en: “ponen” (I went), “saapitten” (I ate), “eduthen” (I took). It is the same whoever is speaking.', 1, 'published', datetime('now'), datetime('now'), 1);
