INSERT INTO vocabulary_translations(item_id, language_id, meaning, natural) VALUES ((SELECT id FROM vocabulary_items WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND text = 'மழை வந்தா நான் வர மாட்டேன்.'), (SELECT id FROM languages WHERE code = 'en'), 'If rain comes I won''t come.', 'If it rains, I won''t come.');
