INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'B1', 'complaints', 'Making a Complaint', 'Complain politely, explain how long a problem has lasted and ask for action.', 'The water has been off in your apartment block for two days.', '“-aa” after a time means “for”: “rendu naalaa” (for two days). Stay polite and say what you want done: “thayavu senju innikke sari pannunga”.', 5, 'published', datetime('now'), datetime('now'), 1);
