INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'past-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The past: “ponen”, “saapitten”, “panneenga”', 'What you did ends in -en: “ponen” (I went), “saapitten” (I ate), “eduthen” (I took). With “neenga” (you, polite) it ends in -eenga: “panneenga?” (did you do?), “vandheenga?” (did you come?). Tamil''s past is not gendered for “I” and “you”.');
