INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'future-tense'), (SELECT id FROM languages WHERE code = 'en'), 'The future: “-(p)pen” and “-laam”', '“I will” ends in -en after the future marker: “endhiruppen” (I''ll get up), “mudichiduven” (I''ll finish it off). “Let''s” ends in -laam: “polaam” (let''s go), “pesalaam” (let''s talk).');
