INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'polite-questions'), (SELECT id FROM languages WHERE code = 'en'), 'Softer requests: “…uveengalaa?”', 'To ask kindly, ask whether the person will do it: “pannuveengalaa?” (would you do?), “tharuveengalaa?” (would you give?), “pesuveengalaa?” (would you speak?). It is softer than the plain “-unga” request (“kudunga”, “pannunga”).');
