INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'liking'), (SELECT id FROM languages WHERE code = 'en'), 'Liking things: “enakku … pidikkum”', 'Tamil says “to me, X is liked”: “enakku coffee pidikkum” (I like coffee), “pidikkaadhu” (don''t like). “Ungalukku enna pidikkum?” asks what someone likes. It is the same whoever is speaking.');
