INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'comparing'), (SELECT id FROM languages WHERE code = 'en'), 'Comparing: “-vida”', 'Add “-vida” (than) to what you compare against: “bussaivida” (than the bus), “adhaivida” (than that), “idhaivida” (than this). Then say what is more: “vilai kammi” (cheaper), “seekiram” (faster).');
