INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'having-to'), (SELECT id FROM languages WHERE code = 'en'), 'Having to: “-anum”', 'Add “-anum” to a verb for what you have to or want to do: “poganum” (have to go), “pesanum” (need to speak), “kattanum” (have to pay). “Enakku … venum” on its own means “I need …”: “enakku leave venum” (I need leave).');
