INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'if-and-when'), (SELECT id FROM languages WHERE code = 'en'), 'If and when: “-naa” and “-appo”', '“-naa” or “-aa” makes “if”: “mazhai vandhaa” (if it rains), “kettaa” (if you ask), “kilambinaa” (if you leave). “-appo” makes “when”: “vandhappo” (when I came).');
