INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'can-and-cant'), (SELECT id FROM languages WHERE code = 'en'), 'Can and can''t: “theriyum” and “mudiyum”', 'For a skill, say “enakku … theriyum” (it is known to me): “enakku drive panna theriyum” (I can drive); “theriyaadhu” is “I can''t”. For what is possible, use “mudiyum” and “mudiyaadhu”: “vara mudiyaadhu” (I can''t come).');
